// Reptile Scales - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// Every scale takes ONE color: blotchy markings are a noise sampled at the scale's
// own cell point, so a blotch never cuts a scale in two. The crevices sink toward
// u_col2 and the tops get a waxy sheen.
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = light scales, u_col2 = dark markings and crevices.

float DENSITY = 13.0 * max(E, 0.05);  // slider E   // MUST match the displacement
float STRETCH = 1.45;
float JITTER  = 0.75;
float MARKINGS = 0.55;  // share of dark scales in the blotches   [0 .. 1]
float SHEEN    = 0.35;  // waxy highlight on the domes             [0 .. 1]

vec3 scaleV = vec3(1.0, 1.0 / STRETCH, 1.0);
vec3 vp = pModel * DENSITY * scaleV;
vec3 vi = floor(vp);
vec3 vf = fract(vp);
float d1 = 8.0;
float d2 = 8.0;
vec3  c1 = vec3(0.0);   // nearest cell point, in cell space
for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
    h3 += dot(h3, h3.yxz + 33.33);
    vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
    vec3 r = g + o - vf;
    float dd = dot(r, r);
    if (dd < d1) { d2 = d1; d1 = dd; c1 = vi + g + o; }
    else if (dd < d2) { d2 = dd; }
}
float crevice = 1.0 - smoothstep(0.0, 0.12, 0.5 * (sqrt(d2) - sqrt(d1)));

// --- markings: value noise (2 octaves) at the scale's center, back in model space
vec3 np = c1 / (DENSITY * scaleV) * 2.2;
float mk = 0.0;
float ma = 0.65;
for (int oct = 0; oct < 2; oct++) {
    vec3 ip = floor(np);
    vec3 fr = fract(np);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);
    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    mk += ma * mix(z0, z1, w.z);
    np *= 2.3;
    ma *= 0.35;
}
mk /= 0.8775;
float dark = step(1.0 - MARKINGS, mk) * smoothstep(0.35, 0.65, mk);

// per-scale brightness jitter
vec3 hs = fract(floor(c1) * vec3(0.1031, 0.1030, 0.0973) + 0.53);
hs += dot(hs, hs.yxz + 33.33);
float jit = fract((hs.x + hs.y) * hs.z);

vec3 scaleCol = mix(ubuf.u_col1, ubuf.u_col2 * 1.6, dark) * (0.85 + 0.3 * jit);
// a lighter rim toward the edge of each scale, as on real scales
scaleCol *= 1.0 + 0.15 * smoothstep(0.3, 0.7, sqrt(d1));
scaleCol = mix(scaleCol, ubuf.u_col2 * 0.5, crevice * 0.8);

// waxy sheen: soft broad highlight
vec3 H = normalize(mainLight_model + viewDir_model);
scaleCol += ubuf.u_col1 * SHEEN * pow(max(dot(n_model, H), 0.0), 24.0) * (1.0 - crevice);

textureCol = scaleCol;

