// Reptile Scales - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Domed scales, a little elongated and tilted like overlapping scales, separated by
// sharp crevices. Each cell of a 3D Voronoi is a scale: a dome that rises from the
// cell border and is pushed up toward the TAIL side, so every scale seems to come
// out from under its neighbour. In scope: d_surf, p, pModel.  Convention: d_surf -= height -> raised.
//
// SPEED. The domes are a couple of hundredths high, so the 27-cell Voronoi runs only
// inside a BAND around the surface, with the height faded to zero at the edge of the
// band (smooth, the field stays continuous). Far from the surface -- where a missed
// ray spends ~100 steps -- this costs one smoothstep. Arithmetic hash, no sin().

float DENSITY = 13.0 * max(E, 0.05);  // slider E   // scales per unit        [6 .. 30]
float HEIGHT  = 0.018 * max(F, 0.0);  // slider F   // dome height (field)    [0 .. 0.05]
float STRETCH = 1.45;   // scales longer along y than across                 [1.0 .. 2.0]
float TILT    = 0.45;   // how much each scale rises toward its tail         [0 .. 0.8]
float JITTER  = 0.75;   // 0 = regular rows, 1 = fully random                [0.4 .. 1.0]

float BAND   = max(0.3, 12.0 * HEIGHT);
float inBand = 1.0 - smoothstep(0.5 * BAND, BAND, abs(d_surf));

if (inBand > 0.0) {
    // anisotropic cells: dividing y makes them longer along y
    vec3 vp = pModel * DENSITY * vec3(1.0, 1.0 / STRETCH, 1.0);
    vec3 vi = floor(vp);
    vec3 vf = fract(vp);

    float d1 = 8.0;
    float d2 = 8.0;
    vec3  r1 = vec3(0.0);   // from the point to the nearest cell point
    for (int gx = -1; gx <= 1; gx++)
    for (int gy = -1; gy <= 1; gy++)
    for (int gz = -1; gz <= 1; gz++) {
        vec3 g = vec3(float(gx), float(gy), float(gz));
        vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
        h3 += dot(h3, h3.yxz + 33.33);
        vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
        vec3 r = g + o - vf;
        float dd = dot(r, r);
        if (dd < d1) { d2 = d1; d1 = dd; r1 = r; }
        else if (dd < d2) { d2 = dd; }
    }

    // Distance from the border with the neighbouring scale (cell units, 0 on it).
    // The dome is built on THIS distance, so it is exactly zero on every border and
    // two neighbouring scales always meet at the same height: the field stays
    // continuous (no steps for the rays to trip on) even with the tilt below.
    float edge = 0.5 * (sqrt(d2) - sqrt(d1));
    float dome = smoothstep(0.0, 0.35, edge) * (1.0 - 0.3 * d1);
    // tilt: higher toward the "tail" side of each scale (away from the cell point
    // along -y), which reads as scales overlapping each other
    dome *= 1.0 + TILT * clamp(r1.y / 0.6, -1.0, 1.0);

    d_surf -= HEIGHT * dome * inBand;
}
